// <WeaponIcon category="突击步枪" size={16} /> — inherits the text color.
export default function WeaponIcon({ category, size = 16, style, className }) {
  const paths = ICONS[category] || ICONS._all;
  return (
    <svg viewBox={VIEWBOX} width={size} height={size} fill="currentColor" aria-hidden="true"
      className={className} style={{ flexShrink: 0, verticalAlign: '-0.15em', ...style }}>
      {paths.map((d, i) => <path key={i} d={d} />)}
    </svg>
  );
}

// Category chip icon: the weapon glyph inside a small badge tinted with the
// category color (used by the filter chips on the weapon/community/official pages).
export function CatChipIcon({ category, color = '#20e870' }) {
  return (
    <span className="chip-icon" style={{ color, background: color + '1f', borderColor: color + '40' }}>
      <WeaponIcon category={category} size={17} />
    </span>
  );
}
